    // the type and syntax fields are skipped.
    // The imports are written out as just a map of path to package id.
    // The errors are written using a custom type that tries to preserve the
    // structure of error types we know about.
    //
    // This method exists to enable support for additional build systems.  It is
    // not intended for use by clients of the API and we may change the format.
    std::tuple<gocpp::slice<unsigned char>, gocpp::error> rec::MarshalJSON(Package* p)
    {
        auto flat = gocpp::InitPtr<flatPackage>([=](auto& x) {
            x.ID = p->ID;
            x.Name = p->Name;
            x.PkgPath = p->PkgPath;
            x.Errors = p->Errors;
            x.GoFiles = p->GoFiles;
            x.CompiledGoFiles = p->CompiledGoFiles;
            x.OtherFiles = p->OtherFiles;
            x.EmbedFiles = p->EmbedFiles;
            x.EmbedPatterns = p->EmbedPatterns;
            x.IgnoredFiles = p->IgnoredFiles;
            x.ExportFile = p->ExportFile;
        });
        if(len(p->Imports) > 0)
        {
            flat->Imports = gocpp::make(gocpp::Tag<gocpp::map<gocpp::string, gocpp::string>>(), len(p->Imports));
            for(auto [path, ipkg] : p->Imports)
            {
                flat->Imports[path] = ipkg->ID;
            }
        }
        return json::Marshal(flat);
    }

    // UnmarshalJSON reads in a Package from its JSON format.
    // See MarshalJSON for details about the format accepted.
    gocpp::error rec::UnmarshalJSON(Package* p, gocpp::slice<unsigned char> b)
    {
        auto flat = new flatPackage {};
        if(auto err = json::Unmarshal(b, & flat); err != nullptr)
        {
            return err;
        }
        *p = gocpp::Init<Package>([=](auto& x) {
            x.ID = flat->ID;
            x.Name = flat->Name;
            x.PkgPath = flat->PkgPath;
            x.Errors = flat->Errors;
            x.GoFiles = flat->GoFiles;
            x.CompiledGoFiles = flat->CompiledGoFiles;
            x.OtherFiles = flat->OtherFiles;
            x.EmbedFiles = flat->EmbedFiles;
            x.EmbedPatterns = flat->EmbedPatterns;
            x.IgnoredFiles = flat->IgnoredFiles;
            x.ExportFile = flat->ExportFile;
        });
        if(len(flat->Imports) > 0)
        {
            p->Imports = gocpp::make(gocpp::Tag<gocpp::map<gocpp::string, Package*>>(), len(flat->Imports));
            for(auto [path, id] : flat->Imports)
            {
                p->Imports[path] = gocpp::InitPtr<Package>([=](auto& x) {
                    x.ID = id;
                });
            }
        }
        return nullptr;
    }

    gocpp::string rec::String(Package* p)
    {
        return p->ID;
    }

    // loaderPackage augments Package with state used during the loading phase
    
    template<typename T> requires gocpp::GoStruct<T>
    loaderPackage::operator T()
    {
        T result;
        result.Package = this->Package;
        result.importErrors = this->importErrors;
        result.loadOnce = this->loadOnce;
        result.color = this->color;
        result.needsrc = this->needsrc;
        result.needtypes = this->needtypes;
        result.initial = this->initial;
        result.goVersion = this->goVersion;
        return result;
    }

    template<typename T> requires gocpp::GoStruct<T>
    bool loaderPackage::operator==(const T& ref) const
    {
        if (Package != ref.Package) return false;
        if (importErrors != ref.importErrors) return false;
        if (loadOnce != ref.loadOnce) return false;
        if (color != ref.color) return false;
        if (needsrc != ref.needsrc) return false;
        if (needtypes != ref.needtypes) return false;
        if (initial != ref.initial) return false;
        if (goVersion != ref.goVersion) return false;
        return true;
    }

    std::ostream& loaderPackage::PrintTo(std::ostream& os) const
    {
        os << '{';
        os << "" << Package;
        os << " " << importErrors;
        os << " " << loadOnce;
        os << " " << color;
        os << " " << needsrc;
        os << " " << needtypes;
        os << " " << initial;
        os << " " << goVersion;
        os << '}';
        return os;
    }

    std::ostream& operator<<(std::ostream& os, const struct loaderPackage& value)
    {
        return value.PrintTo(os);
    }

    // loader holds the working state of a single call to load.
    
    template<typename T> requires gocpp::GoStruct<T>
    loader::operator T()
    {
        T result;
        result.pkgs = this->pkgs;
        result.Config = this->Config;
        result.sizes = this->sizes;
        result.parseCache = this->parseCache;
        result.parseCacheMu = this->parseCacheMu;
        result.exportMu = this->exportMu;
        result.requestedMode = this->requestedMode;
        return result;
    }

    template<typename T> requires gocpp::GoStruct<T>
    bool loader::operator==(const T& ref) const
    {
        if (pkgs != ref.pkgs) return false;
        if (Config != ref.Config) return false;
        if (sizes != ref.sizes) return false;
        if (parseCache != ref.parseCache) return false;
        if (parseCacheMu != ref.parseCacheMu) return false;
        if (exportMu != ref.exportMu) return false;
        if (requestedMode != ref.requestedMode) return false;
        return true;
    }

