    template<typename T> requires gocpp::GoStruct<T>
    parseValue::operator T()
    {
        T result;
        result.f = this->f;
        result.err = this->err;
        result.ready = this->ready;
        return result;
    }

    template<typename T> requires gocpp::GoStruct<T>
    bool parseValue::operator==(const T& ref) const
    {
        if (f != ref.f) return false;
        if (err != ref.err) return false;
        if (ready != ref.ready) return false;
        return true;
    }

